export const HERE = dirname(fileURLToPath(import.meta.url));
export const sha256 = bytes => createHash('sha256').update(bytes).digest('hex');
export class Refusal extends Error { constructor(code, detail) { super(`${code}: ${detail}`); this.code = code; } }
export function requireThat(value, code, detail = '') { if (!value) throw new Refusal(code, detail); }
export const readManifest = async () => JSON.parse(await readFile(join(HERE, 'execution-manifest.json'), 'utf8'));
