  const tar = qualificationFault?.tarCommand ? spawn(qualificationFault.tarCommand[0], qualificationFault.tarCommand.slice(1), { stdio: ['pipe', 'pipe', 'pipe'] }) : spawn('tar', ['-xf', '-', '-C', destination], { stdio: ['pipe', 'pipe', 'pipe'] });
