  const counter = new Transform({ transform(chunk, _encoding, done) { bytes += chunk.length; digest.update(chunk); if(qualificationFault?.breakStream) done(new Error('qualification-stream-fault')); else done(null, chunk); } });
  const status = child => new Promise(r => { let error; child.on('error', e => { error = String(e); }); child.on('close', (code, signal) => r({ code, signal, error })); });
  const ends = Promise.all([status(git), status(tar)]);
  const streams = Promise.allSettled([pipeline(git.stdout, counter, tar.stdin), pipeline(git.stderr, gitErr), pipeline(tar.stderr, tarErr), pipeline(tar.stdout, tarOut)]);
  let timedOut = false; let outcome;
