    if (row.kind === 'surface') { await o.capture(row.id); requireThat(before.lane === 'actual-host-synthetic-auth', 'HOST', 'direct module is not actual host'); await (adapters.visualAX ?? publicAdapters.visualAX)(row, o); }
    if (row.kind === 'pointer') { const index = { weight: 1, sleep: 2, water: 3, exercise: 4 }[row.metric]; try { await o.pointer(`.mt-tabs button:nth-child(${index})`); } catch(e) { if (e.code !== 'HIT') throw e; await o.stripScroll(1); await o.pointer(`.mt-tabs button:nth-child(${index})`); } noEffect(before, await o.snapshot()); }
    if (row.kind === 'weight-positive') { await o.evaluate('window.__met05.resetEmptyFixture()'); await o.command('Page.reload', {}); await o.wait('window.__met05?.ready && document.querySelector(".module-metrics")'); await o.evaluate('window.__met05.settledBoundary()'); const empty = await o.snapshot(); await o.log(row.lang, 71.25, row.id); loggedOracle(empty,await o.snapshot(),71.25,row.id); await o.command('Page.reload',{}); await o.wait('window.__met05?.ready && document.querySelector(".module-metrics")'); loggedOracle(empty,await o.snapshot(),71.25,row.id); await o.capture(row.id); }
    if (row.kind === 'keyboard') { requireThat(adapters.focus?.identity === m.focus.function, 'METHOD', 'frozen compatibility adapter missing'); await adapters.focus.walk(row,o,artifacts); await (adapters.keyboardActions ?? publicAdapters.keyboardActions)(row,o); await o.capture(row.id); }
