    if (row.kind === 'retry') { await o.evaluate('window.__met05.resetEmptyFixture()'); await o.command('Page.reload',{}); await o.wait('window.__met05?.ready && document.querySelector(".module-metrics")'); await o.evaluate('window.__met05.settledBoundary();window.__met05.denyOnce()'); const empty=await o.snapshot(); await o.log('en',71.25,row.id); const failed=await o.snapshot(); requireThat(failed.failureVisible && isDeepStrictEqual(empty.bytes,failed.bytes),'BUSINESS','denied write invisible or committed'); await o.pointer('.mt-save-failure button:first-of-type'); await o.wait('!document.querySelector(".mt-save-failure")'); loggedOracle(empty,await o.snapshot(),71.25,row.id); await o.capture(row.id); }
