if (process.argv[1] && resolve(process.argv[1])===fileURLToPath(import.meta.url)) main(process.argv[2]).catch(e=>{process.stderr.write(`${e.stack}\n`);process.exitCode=1;});

export const publicAdapters = {
  async visualAX(row,o) {
    const tree=await o.command('Accessibility.getFullAXTree',{}),lang=row.lang ?? (await o.snapshot()).lang;
    const labels=lang==='zh'?['睡眠','饮水','运动','自定义']:['Sleep','Water','Exercise','Custom'];
    for(const label of labels){const nodes=tree.nodes.filter(n=>!n.ignored&&n.role?.value==='button'&&n.name?.value.includes(label)&&n.name?.value.includes(lang==='zh'?'计划中':'Planned'));requireThat(nodes.length===1&&nodes[0].properties?.some(p=>p.name==='disabled'&&p.value?.value===true),'AX',label);}
    // Screenshot legibility/selected appearance remains independent human acceptance, never inferred by DOM.
    await o.journal.record('visual-review-required',{row:row.id,reason:'screenshot legibility/selected state not machine accepted'});
  },
  async entry(row,o,origin) {
    if(row.entry==='rail'){await o.command('Page.navigate',{url:`${origin}/app/dashboard?__met_lang=${row.lang}&__met_theme=light&__met_lane=host`});await o.wait('window.__met05?.ready && !!document.querySelector(".app-rail")');await o.pointer(`.app-rail [aria-label="${row.lang==='zh'?'指标追踪':'Metrics'}"]`);await o.wait('!!document.querySelector(".module-metrics")');}
    else if(row.entry==='cmdk'){await o.key('k',4);await o.wait('!!document.querySelector(".cmdk-input")');await o.enter('.cmdk-input',row.lang==='zh'?'体重':'Weight');await o.wait('!!document.querySelector(".cmdk-row")');const choice=await o.evaluate('Array.from(document.querySelectorAll(".cmdk-row")).map((e,index)=>({index,text:e.textContent}))');requireThat(choice.filter(c=>/Metrics|指标追踪/.test(c.text)).length===1,'CMDK','unique actual module jump');const found=choice.find(c=>/Metrics|指标追踪/.test(c.text));await o.pointer(`#cmdk-row-${found.index}`);await o.wait('!document.querySelector(".cmdk-input") && !!document.querySelector(".module-metrics")');}
    else {const url=new URL(row.path,origin);url.searchParams.set('__met_lang',row.lang);url.searchParams.set('__met_theme','light');url.searchParams.set('__met_lane','host');await o.mount(url.href,row);await o.command('Page.reload',{});await o.wait('window.__met05?.ready && document.querySelector(".module-metrics")');}
  },
  async keyboardActions(row,o) {
    const focus=()=>o.evaluate('({text:document.activeElement?.textContent,disabled:document.activeElement?.disabled,weight:document.activeElement?.matches(".mt-tabs button:first-child"),log:document.activeElement?.matches(".mt-primary")})');
    async function seek(name,reverse=false){for(let i=0;i<140;i++){const at=await focus();requireThat(!at.disabled,'KEYBOARD','disabled Planned focused');if(at[name])return;await o.key('Tab',reverse?8:0);}throw new Refusal('KEYBOARD',`cannot reach ${name}`);}
    await seek('weight');await o.key('Enter');plannedOracle(await o.snapshot());await o.key(' ');plannedOracle(await o.snapshot());
    for(const key of ['Enter',' ']){await seek('log',true);await o.key(key);await o.wait('!!document.querySelector(".mt-modal-card")');requireThat((await o.snapshot()).dialogs===1,'KEYBOARD','exact one Log dialog');await o.pointer('.mt-close');await o.wait('!document.querySelector(".mt-modal-card")');}
    await seek('weight',true);await o.key('Tab');const next=await focus();requireThat(!next.disabled&&!next.weight,'KEYBOARD','next enabled goal control');
  },
  async accountSource(row,o) {
    const baseline=await o.snapshot();requireThat(baseline.scope.kind==='account'&&baseline.scope.accountId==='met05-synthetic-A','ACCOUNT','real gate A');
    if(row.case==='identity'){
      await o.evaluate('window.__met05.publishIdentity(null)');await o.wait('!document.querySelector(".module-metrics")');const locked=await o.snapshot();requireThat(locked.scope.kind==='locked','ACCOUNT','locked gate');
      await o.evaluate('window.__met05.publishIdentity("met05-synthetic-B")');await o.wait('window.__met05.observe().scope.accountId==="met05-synthetic-B" && !!document.querySelector(".module-metrics")');const b=await o.snapshot();requireThat(b.scope.kind==='account'&&JSON.parse(b.bytes[b.key]).profile.targetWeightKg===85,'ACCOUNT','B sentinel');
      await o.evaluate('window.__met05.publishIdentity("met05-synthetic-A")');await o.wait('window.__met05.observe().scope.accountId==="met05-synthetic-A" && !!document.querySelector(".module-metrics")');const a=await o.snapshot();requireThat(isDeepStrictEqual(baseline.bytes,a.bytes)&&a.writes===baseline.writes&&a.removes===baseline.removes,'ACCOUNT','transition wrote metric data');
      requireThat(a.firstRender.length>0,'ACCOUNT','first rendered identity evidence absent');await o.journal.record('first-render-needs-independent-review',{row:row.id,firstRender:a.firstRender,locked,b,a});
    }else{
      await o.evaluate('window.__met05.mixedSourceFixture()');const injected=await o.snapshot();await o.command('Page.reload',{});await o.wait('window.__met05?.ready && document.querySelector(".module-metrics")');const after=await o.snapshot();plannedOracle(after);requireThat(isDeepStrictEqual(injected.bytes,after.bytes)&&!after.content.includes('mixed-source'),'SOURCE','normalization persisted or rendered Sleep record');
    }
  },
};
